// 节点定义
function ListNode(val, next) { this.val = (val===undefined ? 0 : val); this.next = (next===undefined ? null : next); }

// ① 迭代版：三指针，O(1) 空间
function reverseList(head) {
  let prev = null, cur = head;
  while (cur !== null) {
    const next = cur.next;  // 暂存后继
    cur.next = prev;        // 反转指针
    prev = cur;             // 前驱前移
    cur = next;             // 当前前移
  }
  return prev;              // prev 成为新头
}

// ② 递归版
function reverseListRec(head) {
  if (head === null || head.next === null) return head; // 基准：空或单节点
  const newHead = reverseListRec(head.next);            // 先反转子链表
  head.next.next = head;   // 后继反过来指自己
  head.next = null;        // 断开原方向，防止成环
  return newHead;
}

// ① 每日温度：单调递减栈，O(n)
function dailyTemperatures(t) {
  const n = t.length, ans = new Array(n).fill(0), stk = [];
  for (let i = 0; i < n; i++) {
    while (stk.length && t[i] > t[stk[stk.length - 1]]) {
      const j = stk.pop();
      ans[j] = i - j;          // i 就是 j 之后第一个更暖的天
    }
    stk.push(i);
  }
  return ans;
}

// ② 滑动窗口最大值：单调递减双端队列，O(n)
function maxSlidingWindow(nums, k) {
  const dq = [], ans = [];     // dq 存下标，对应值单调递减
  for (let i = 0; i < nums.length; i++) {
    while (dq.length && nums[dq[dq.length - 1]] <= nums[i]) dq.pop(); // 队尾清理
    dq.push(i);
    if (dq[0] <= i - k) dq.shift();        // 队首过期出窗
    if (i >= k - 1) ans.push(nums[dq[0]]); // 队首即窗口最大
  }
  return ans;
}

// 通用写法：哈希表 + 双向链表（虚拟头尾哨兵）
class Node {
  constructor(k, v) { this.k = k; this.v = v; this.prev = null; this.next = null; }
}
class LRUCache {
  constructor(capacity) {
    this.cap = capacity;
    this.map = new Map();
    this.head = new Node(0, 0); this.tail = new Node(0, 0);
    this.head.next = this.tail; this.tail.prev = this.head;
  }
  // 摘除已知节点 O(1)
  remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
  // 头插 O(1)
  addToHead(node) {
    node.next = this.head.next; node.prev = this.head;
    this.head.next.prev = node; this.head.next = node;
  }
  get(key) {
    if (!this.map.has(key)) return -1;
    const node = this.map.get(key);
    this.remove(node); this.addToHead(node);  // 提鲜
    return node.v;
  }
  put(key, value) {
    if (this.map.has(key)) {
      const node = this.map.get(key);
      node.v = value;
      this.remove(node); this.addToHead(node);
      return;
    }
    if (this.map.size >= this.cap) {           // 淘汰最久未用（尾节点）
      const old = this.tail.prev;
      this.remove(old); this.map.delete(old.k);
    }
    const node = new Node(key, value);
    this.map.set(key, node); this.addToHead(node);
  }
}

